  // ── Screen: atlas ─────────────────────────────────────────────────────────────────────
  'help.ctx.atlas.title': 'Atlas',
  'help.ctx.atlas.summary':
    'Atlas هو بصمة سفرك على خريطة العالم: كل دولة أخذتك إليها رحلة تكون ملوّنة، ويمكنك إضافة الدول التي زرتها قبل TREK يدويًا. كبّر الخريطة لترى المناطق، واحتفظ بقائمة أمنيات بالأماكن التي ما زلت تريد رؤيتها، واقرأ أرقامك في اللوحة الزجاجية في الأسفل.',
  'help.ctx.atlas.bullet.1':
    'الخريطة: الدول المُزارة تحمل لونًا يبقى لها، والدول المخطط زيارتها لها حدود متقطعة، ودول قائمة الأمنيات تظليل مائل، وكل ما عداها رمادي. مرّر المؤشر فوق دولة لترى رحلاتها وأماكنها وأول زيارة وآخر زيارة.',
  'help.ctx.atlas.bullet.2':
    'البحث في الأعلى: اكتب دولة أو مكانًا. اختيار دولة يطير بالخريطة إليها ويفتح نافذتها المنبثقة؛ واختيار مكان يهبط بك في منطقته لتتمكن من تعيينها.',
  'help.ctx.atlas.bullet.3':
    '«إظهار الدول المخطط زيارتها»، أعلى اليمين: يكشف دول رحلاتك القادمة. لا يظهر المفتاح إلا ما دامت لديك رحلات قادمة.',
  'help.ctx.atlas.bullet.4':
    'اللوحة في الأسفل: تبويب الإحصائيات مع الدول والرحلات والأماكن والمدن والأيام والقارات وسلسلتك؛ وتبويب قائمة الأمنيات مع ما ينتظرك بعد.',
  'help.ctx.atlas.bullet.5':
    'المناطق: من مستوى التكبير 5 تنتقل الخريطة إلى الولايات والمقاطعات، وكل واحدة قابلة للنقر لتعيينها أو إزالة تعيينها.',
  'help.ctx.atlas.bullet.6':
    'Dawarich: مع توصيل الإضافة، تشطب لوحة على يسار الإحصائيات الأمنيات وتضيف دولًا من تسجيلاتك، ولا تفعل ذلك أبدًا دون تأكيدك.',
  // mark-country
  'help.guide.mark-country.title': 'تعيين دولة كمُزارة',
  'help.guide.mark-country.goal': 'أضف دولة زرتها قبل TREK، لتشملها الخريطة وعدّادك.',
  'help.guide.mark-country.step.1': 'اكتب اسم الدولة في مربع البحث أعلى الخريطة.',
  'help.guide.mark-country.step.2': 'اخترها من القائمة. تطير الخريطة إليها وتُفتح نافذة منبثقة لتلك الدولة.',
  'help.guide.mark-country.step.3': 'اختر «تعيين كمُزار».',
  'help.guide.mark-country.result':
    'تأخذ الدولة لونها على الخريطة ويزيد عدّاد «الدول» واحدًا. هذا اللون دائم: تعيين مزيد من الدول لا يعيد ترتيب ألوان البقية أبدًا.',
  'help.guide.mark-country.tip.1':
    'النقر على دولة رمادية على الخريطة يفتح النافذة المنبثقة نفسها؛ والبحث هو الطريق المضمون للدول الصغيرة.',
  'help.guide.mark-country.tip.2': 'الدولة التي تعيّنها يدويًا تُحسب دائمًا كمُزارة، أيًا كانت تواريخ أي رحلة إليها.',
  // unmark-country
  'help.guide.unmark-country.title': 'إزالة دولة عيّنتها',
  'help.guide.unmark-country.goal': 'أزل دولة معيّنة يدويًا من الخريطة مجددًا.',
